{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)"
    },
    {
      "name": "MvPowerSeries.coeff_eq_zero_of_lt_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  ↑((Finsupp.weight w) d) < MvPowerSeries.weightedOrder w f → (MvPowerSeries.coeff d) f = 0"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "Finset.sum_schlomilch_le'",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 1 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u →\n        ∀ (n : ℕ), ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u (k + 1)) ≤ ∑ k ∈ Finset.Ico (u 0 + 1) (u n + 1), f k"
    },
    {
      "name": "descPochhammer_eval_div_factorial_le_sum_choose",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pochhammer",
      "kind": "theorem",
      "type": "∀ {n : ℕ},\n  n ≠ 0 →\n    ∀ {ι : Type u_2} {t : Finset ι} (p : ι → ℕ) (w : ι → ℝ),\n      (∀ i ∈ t, 0 ≤ w i) →\n        ∑ i ∈ t, w i = 1 →\n          ↑n - 1 ≤ ∑ i ∈ t, w i * ↑(p i) →\n            Polynomial.eval (∑ i ∈ t, w i * ↑(p i)) (descPochhammer ℝ n) / ↑n.factorial ≤\n              ∑ i ∈ t, w i * ↑((p i).choose n)"
    }
  ]
}
